class FrmonShellClient(Exit):
    """FrmonShellClient command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None, expected_prompt=r"^\$\s*$",
                 target_newline="\r\n"):
        """
        Go to FRMONSHELL.

        :param connection: Moler connection to device, terminal when command is executed.
        :param prompt: Prompt of the starting shell.
        :param newline_chars: Characters to split lines.
        :param runner: Runner to run command.
        :param expected_prompt: Prompt of the target shell reached after entering to FRMONSHELL state.
        :param target_newline: Newline chars on remote system where ssh connects.
        """
        super(FrmonShellClient, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                               runner=runner, expected_prompt=expected_prompt,
                                               target_newline=target_newline)

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        cmd = "frmonShellClient"
        return cmd


